namespace local_brokenlinks\external;

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_single_structure;
use core_external\external_value;
use local_brokenlinks\local\scan_manager;

/**
 * Whether the link check of a course is still waiting or running, so the report page can say when it is done.
 *
 * @package    local_brokenlinks
 * @copyright  2026 Biruh Alemnew <biruh@biruh.org>
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class get_scan_status extends external_api {
    /**
     * Parameters.
     *
     * @return external_function_parameters
     */
    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'courseid' => new external_value(PARAM_INT, 'Course id'),
        ]);
    }

    /**
     * The state of the course's link check.
     *
     * @param int $courseid
     * @return array
     */
    public static function execute(int $courseid): array {
        ['courseid' => $courseid] = self::validate_parameters(self::execute_parameters(), ['courseid' => $courseid]);
        $context = \context_course::instance($courseid);
        self::validate_context($context);
        require_capability('local/brokenlinks:view', $context);

        if ($pending = scan_manager::get_pending($courseid)) {
            $status = $pending->status == scan_manager::STATUS_RUNNING ? 'running' : 'queued';
        } else {
            $latest = scan_manager::get_latest($courseid);
            $status = !$latest ? 'none' : ($latest->status == scan_manager::STATUS_FAILED ? 'failed' : 'finished');
        }
        return ['status' => $status];
    }

    /**
     * Return value.
     *
     * @return external_single_structure
     */
    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'status' => new external_value(PARAM_ALPHA, 'queued, running, finished, failed or none'),
        ]);
    }
}
